TLM.f("Sancti/11-09",{"officium":"In Dedicatione Basilicæ Ss. Salvatoris","rule":["ex C8;","Gloria","Credo","Prefatio=Dedicatio"],"ruleInherited":["Gloria","Credo","Prefatio=Dedicatio"],"fallback":"Commune/C8","from":{"Introitus":"Commune/C8","Oratio":"Commune/C8","Lectio":"Commune/C8","Graduale":"Commune/C8","GradualeP":"Commune/C8","Tractus":"Commune/C8","Evangelium":"Commune/C8","Offertorium":"Commune/C8","Communio":"Commune/C8","Postcommunio":"Commune/C8"},"sections":{"Introitus":[{"k":"ref","la":"Gen 28:17"},{"k":"text","la":"Terríbilis est locus iste: hic domus Dei est et porta cœli: et vocábitur aula Dei. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 83:2-3"},{"k":"text","la":"Quam dilécta tabernácula tua, Dómine virtútum! concupíscit, et déficit ánima mea in átria Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Terríbilis est locus iste: hic domus Dei est et porta cœli: et vocábitur aula Dei. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui nobis per síngulos annos hujus sancti templi tui consecratiónis réparas diem, et sacris semper mystériis repæséntas incólumes: exáudi preces pópuli tui, et præsta; ut, quisquis hoc templum benefícia petitúrus ingréditur, cuncta se impetrásse lætétur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Apocalýpsis beáti Joánnis Apóstoli"},{"k":"ref","la":"Apoc 21:2-5"},{"k":"text","la":"In diébus illis: Vidi sanctam civitátem Jerúsalem novam descendéntem de cœlo a Deo, parátam sicut sponsam ornátam viro suo. Et audívi vocem magnam de throno dicéntem: Ecce tabernáculum Dei cum homínibus, et habitábit cum eis. Et ipsi pópulus ejus erunt, et ipse Deus cum eis erit eórum Deus: et abstérget Deus omnem lácrimam ab óculis eórum: et mors ultra non erit, neque luctus neque clamor neque dolor erit ultra, quia prima abiérunt. Et dixit, qui sedébat in throno: Ecce, nova fácio ómnia."}],"Graduale":[{"k":"text","la":"Locus iste a Deo factus est, inæstimábile sacraméntum, irreprehensíbilis est."},{"k":"text","la":"Deus, cui astat Angelórum chorus, exáudi preces servórum tuórum. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 137:2"},{"k":"text","la":"Adorábo ad templum sanctum tuum: et confitébor nómini tuo. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 137:2"},{"k":"text","la":"Adorábo ad templum sanctum tuum: et confitébor nómini tuo. Allelúja."},{"k":"text","la":"Bene fundáta est domus Dómini supra firmam petram. Allelúja.","mark":"V"}],"Tractus":[{"k":"text","la":"Locus iste a Deo factus est, inæstimábile sacraméntum, irreprehensíbilis est."},{"k":"text","la":"Deus, cui astat Angelórum chorus, exáudi preces servórum tuórum.","mark":"V"},{"k":"ref","la":"Ps 124:1-2"},{"k":"text","la":"Qui confídunt in Dómino, sicut mons Sion: non commovébitur in ætérnum, qui hábitat in Jerúsalem."},{"k":"text","la":"Montes in circúitu ejus, et Dóminus in circúitu pópuli sui, ex hoc nunc, et usque in sǽculum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 19:1-10"},{"k":"text","la":"In illo témpore: Ingréssus Jesus perambulábat Jéricho. Et ecce, vir nómine Zachǽus: et hic princeps erat publicanórum, et ipse dives: et quærébat vidére Jesum, quis esset: et non póterat præ turba, quia statúra pusíllus erat. Et præcúrrens ascéndit in árborem sycómorum, ut vidéret eum; quia inde erat transitúrus. Et cum venísset ad locum, suspíciens Jesus vidit illum, et dixit ad eum: Zachǽe, festínans descénde; quia hódie in domo tua opórtet me manére. Et festínans descéndit, et excépit illum gaudens. Et cum vidérent omnes, murmurábant, dicéntes, quod ad hóminem peccatórem divertísset. Stans autem Zachǽus, dixit ad Dóminum: Ecce, dimídium bonórum meórum, Dómine, do paupéribus: et si quid áliquem defraudávi, reddo quádruplum. Ait Jesus ad eum: Quia hódie salus dómui huic facta est: eo quod et ipse fílius sit Abrahæ. Venit enim Fílius hóminis quǽrere et salvum fácere, quod períerat."}],"Offertorium":[{"k":"ref","la":"1 Par 29:17-18"},{"k":"text","la":"Dómine Deus, in simplicitáte cordis mei lætus óbtuli univérsa; et pópulum tuum, qui repértus est, vidi cum ingénti gáudio: Deus Israël, custódi hanc voluntátem, allelúja."}],"Secreta":[{"k":"text","la":"Annue, quǽsumus, Dómine, précibus nostris: ut, dum hæc vota præséntia réddimus, ad ætérna præmia, te adjuvánte, perveníre mereámur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 21:13"},{"k":"text","la":"Domus mea domus oratiónis vocábitur, dicit Dóminus: in ea omnis, qui petit, áccipit; et qui quærit, invénit; et pulsánti aperiétur. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Deus, qui de vivis et electis lapídibus ætérnum majestáti tuæ prǽparas habitáculum: auxiliáre pópulo tuo supplicánti; ut, quod Ecclésiæ tuæ corporálibus próficit spátiis, spirituálibus amplificétur augméntis."},{"k":"macro","name":"Per Dominum"}]},"hr":{"73e60c49f8950305":{"t":"Post 28, 17, Ps 83, 2-3\n(Post 28, 17) Strašno je mjesto ovo. Ovdje je dom Gospodnji i vrata nebeska. I zvat će se dvor Božji. (Ps. 83, 2-3) Kako su mili stanovi tvoji, Gospodine vojska! Duša moja čezne i gine za dvorima Gospodnjim.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Post 28, 17) Strašno je mjesto ovo. Ovdje je dom Gospodnji i vrata nebeska. I zvat će se dvor Božji.","kn":"(Posl. 28, 17). Strašno je ovo mjesto; ovdje . je dom Gospodnji i vrata nebeska i zvat će se. dvor Božji. (Ps. 83, 2) Kako su mili stanovi Tvoji, Gospodine nad vojskama! Čezne i gine duša^ moja za dvorima Gospodnjim! Slava Ocu . . . Strašno . . .","knRef":"Kniewald 1942, str. 834–835 (snimka 418) (OCR)"},"561ae007cff8cf10":{"t":"<i>Pomolimo se</i>.\nBože, koji nam daješ da svake godine slavimo dan posvećenja ovoga svetog hrama svoga i da vazda živi i zdravi sudjelujemo u svetim otajstvima usliši molitve tvoga puka i podaj da se svatko tko uđe u ovaj hram da te zamoli za koju milost razveseli jer je sve dobio.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji nam svake godine obnavljaš dan posvećenja ovoga svoga svetoga hrama i koji nas vazda dovodiš neokaljane k svetim tajnama: usliši molbe puka svoga i podaj, da se svaki, tko uniđe u ovaj hram moleći Te za pomoć raduje, što je sve izmolio; po G, n.","knRef":"Kniewald 1942, str. 834–835 (snimka 418) (OCR)"},"4aa23417dfe9920e":{"t":"Otk 21, 2-5\nČitanje knjige Otkrivenja bl. Ivana apostola. U one dane vidio sam sveti grad, novi Jeruzalem, kako silazi od Boga s neba, opremljen poput zaručnice nakićene za svog muža. I čuo sam s prijestolja jaki glas kako objavljuje: Evo Božjega šatora među ljudima! On će stanovati posred njih. Oni će biti njegov narod, i sam će Bog biti s njima. On će otrti svaku suzu s njihovih očiju. Smrti više neće biti, niti će više biti tuge ni jauka ni boli, jer je prošlo što je bilo prije. I onaj koji sjedi na prijestolju reče: Evo sve činim novo!","kn":"Čitanje knjige Otkrivenja bi. Ivana Apostola (21, 2-5). U one dame vidio sam sveti grad, novi Jeru- * zalem, gdje silazi s neba, od Boga opremljen kao nakićena zaručnica za svogai muža. I čuo sam, gdje s prijestolja govori silan glas: Evo Božjega šatora među ljudima, i stanovat će s njima, I oni će biti njegov narod, a sam će Bog s njima biti njihov Bog. I otrt će svakui suzu s njihovih očiju, i ne će više biti ni smrti ni tuge, ni jauka ni boli ne će više biti, jer je prošlo, što je bilo prije. I reče omaj, koji sjedi na prijestolju: Evo, obnavljam sve!","knRef":"Kniewald 1942, str. 834–835 (snimka 418) (OCR)"},"3225718f149f2b17":{"t":"Bog je učinio ovo mjesto neprocjenjivom i nepovredivom svetinjom. Bože, koga dvori zbor anđela, usliši molbe slugu svojih.\n\nPs 137, 2\n<i>Aleluja</i>, <i>aleluja</i>.\nKlanjat ću se u svetom hramu tvojemu i slavit ću ime tvoje. <i>Aleluja</i>.","kn":"Mjesto je ovo od Boga učinjeno, nejorocjenjiva je svetinja i nepovredivo. Bože, koga dvori anđeoski zbor, usliši molbe slugu svojih!\n\nAleluja, aleluja (Ps. 137, 2). Klamjat ću se u hramu svetomu Tvojemu i slavit ću ime Tvoje, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 834–835 (snimka 418) (OCR)"},"e508ac053ab6ff32":{"t":"Lk 19, 1-10\nSlijedi sveto Evanđelje po Luki. U ono vrijeme uđe Isus u Jerihon i prođe kroz grad. Prvak carinika, bogati Zahej, želio je vidjeti Isusa, tko je on. Ali nije mogao od mnoštva jer je bio niska rasta. Zato potrča naprijed, popne se na divlju smokvu da ga vidi, jer je tuda imao proći. Kad Isus dođe na ono mjesto, podiže oči, vidi ga i reče mu: Zaheju, siđi brzo, jer danas trebam biti u tvojoj kući. I on brzo siđe i primi ga radosno. Svi koji su vidjeli mrmljali su što se svratio takvom grješniku. Zahej tada pristupi Gospodinu i reče: Gospodine, evo polovicu svog imanja dajem siromasima. I ako sam koga prevario, vraćam četverostruko. Isus mu odgovori: Danas je došao spas u ovu kuću, jer je i on Abrahamov sin. Sin je čovječji došao da potraži i spasi što je bilo propalo.","kn":"t Slijedi sveto evanđelje po Luki (19, 1-10). U ono vrijeme ušav Isus prođe kroz Jerihon. I čovjek Zahej, prvak carinika, koji je . bio bogat, želio je vidjeti Isusa, tko je, ali nije mogao radi naroda, jer je bio malena stasa. Zato potrca naprijed i uspne se na divlju smokvu, da ga vidi, jer je imao proći onuda. Kad Isu.s dođe na ono mjesto, pogleda gore, vidje ga i reče mu: Zaheje, siđi brzo, jer danas treba da budem u tvojoj kući. I siđe brzo i primi ga radosno. A svi, koji su to vidjeli, mrmljali su, što se svratio k grješniku. Tada Zahej pristupi Gospodinu i reče: Gospodine, evo dajem siromasima polovicu svoga imetka, i ako sam koga prevario, vraćam četverostruko. Isus mu odgovori: Danas je došao ^as ovoj kući, jer je i on sin Abrahamov. Jer je Sin čovječji došao, da potraži i .spasi, što je bilo izgubljeno.","knRef":"Kniewald 1942, str. 834–835 (snimka 418) (OCR)"},"9ea4c74a142b3095":{"t":"1 Ljet 29, 17 i 18\nGospodine Bože, radostan sam ti prikazao sve u prostodušnosti srca svoga. I vidjeh puk tvoj ovdje prisutan u velikoj radosti. Čuvaj ovu volju, Bože Izraelov, <i>aleluja</i>.","kn":"(I. Kron. 29, 17). Gospodine, Bože, prikazao s*am Ti sve u prostodušnosti srca svoga i vidjeh puk Tvoj u velikoj radosti: čuvaj ovu volju. Bože Izraelov, aleluja!","knRef":"Kniewald 1942, str. 836–837 (snimka 419) (OCR)"},"8c4bc03e8bbd00d9":{"t":"Usliši, molimo, Gospodine, naše molitve i dok ti prinosimo ove želje da zavrijedimo doći do vječne nagrade.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prikloni se, molimo. Gospodine, prošnjama našim, da mi, koji ovdje sada ove darove prinosimo, zaslužimo doći do vječne nagrade, po G. n.","knRef":"Kniewald 1942, str. 836–837 (snimka 419) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"fdcb21aef508db8b":{"t":"Mt 21, 13\nGospodin veli: Kuća je moja kuća molitve. Svaki tko u njoj moli, dobit će. I tko traži, naći će. I onomu koji kuca otvorit će se.","kn":"(Mt. 21, 13). Kuća će se moja zvati domom molitve; svaki, tko u njoj moli, dobit će: i tko traži, naći 6e: i onomu, koji kuca, otvorit će se.","knRef":"Kniewald 1942, str. 836–837 (snimka 419) (OCR)"},"12eb5d7eddd97e44":{"t":"<i>Pomolimo se</i>.\nBože, koji svojemu veličanstvu pripravljaš prebivalište od živoga i izabranoga kamenja, pomozi svojemu puku koji te moli, da se ono što podiže Crkvi vidljivu veličinu proširi duhovnim porastom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji svome veličanstvu pripravljaš stan od živog i izabra,nog kamenja, pomozi puku svome, koji Te moli, da se uzveliča duhovnim darovima, što Crkvi koristi u tjelesnom prostoru; po G. n.","knRef":"Kniewald 1942, str. 836–837 (snimka 419) (OCR)"},"adad0f7f2fcbfa9b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože. – Ti si s jedinorođenim Sinom tvojim i s Duhom Svetim jedan Bog, jedan Gospodin, ne u jedinstvu jedne osobe, već u Trojstvu jedine biti. Što naime po tvojoj objavi vjerujemo o tvojoj slavi, to isto bez razlike i razlučivanja vjerujemo i o tvome Sinu i o Duhu Svetome. Tako se u ispovijedanju istinitog i vjekovječnog božanstva klanjamo i vlastitosti osoba i jedinstvu biti i jednakosti veličanstva. – Koje hvale anđeli i arkanđeli, kerubini i serafini koji ne prestaju svaki dan klicati govoreći složnim glasom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Go. spodine sveti, Oće svemogući, vječni Bože, koji si sa Sinom svojim i s Duhom Svetim jedan Bog i je- dan Gospodin: ne u jedinstvu osobe, nego u Trojstvu jedne biti. Jer sve, što po Tvojem otkrivenju vjerujemo o Tvojoj slavi, to bez razlike i razlučivanja mislimo i o Sinu Tvoj emu i o Duhu Svetomu. Ispovijedajući pravo i vječno Božanstvo, klanjamo se tako i vlastitosti u osobama i jedinstvu u biti i jednakosti u veličanstvu, koje hvale anđeli i arkanđeli, kerubini i serafini, koji ne prestaju klicati svakog dana jednoglasno govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"}}});
